// ── Shot Counter & CSV Writer ─────────────────────────────────────────────
// fs and path injected via node libs[] — no require() needed.
//
// Writes ONLY to /data/eap_shots  (Node-RED container internal path).
// On the host this maps to: /mnt/nfs/nodered/data/eap_shots/
// A host-side cron job copies files to /home/sie/node-red_csv_writer/ every hour.
//
// Logic:
//  - machine_shot_count : any CHANGE in Total_Good_Count → +1
//  - counter            : increments only when new Total_Good_Count > 0
//  - Shift A  08:00–20:00  →  /data/eap_shots/ShiftA_YYYY-MM-DD.csv
//  - Shift B  20:00–08:00  →  /data/eap_shots/ShiftB_YYYY-MM-DD.csv
//  - Counters reset per machine at each shift boundary.

const CSV_DIR = '/data/eap_shots';

// ─── helpers ─────────────────────────────────────────────────────────────────
function pad(n) { return String(n).padStart(2, '0'); }

function getShiftInfo(now) {
  const h   = now.getHours();
  const fmt = (d) =>
    d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
  if (h >= 8 && h < 20) {
    return { shift: 'A', dateLabel: fmt(now) };
  }
  const startDate = new Date(now);
  if (h < 8) startDate.setDate(startDate.getDate() - 1);
  return { shift: 'B', dateLabel: fmt(startDate) };
}

function csvFilePath(shift, dateLabel) {
  return CSV_DIR + '/Shift' + shift + '_' + dateLabel + '.csv';
}

function appendRow(filePath, row) {
  let isNew = false;
  try {
    const stat = fs.statSync(filePath);
    isNew = stat.size === 0;
  } catch (e) {
    isNew = true;
  }
  const line = [
    row.timestamp, row.shift, row.date_label,
    row.machine_id, row.machine_name,
    row.total_good_count, row.machine_shot_count, row.counter
  ].join(',') + '\n';
  if (isNew) {
    fs.writeFileSync(
      filePath,
      'timestamp,shift,date_label,machine_id,machine_name,' +
      'total_good_count,machine_shot_count,counter\n' + line,
      'utf8'
    );
  } else {
    fs.appendFileSync(filePath, line, 'utf8');
  }
}

// ─── guard ───────────────────────────────────────────────────────────────────
const entry = msg.payload;
if (!entry || !entry.parameters) return null;

const rawGC = entry.parameters.Total_Good_Count;
if (rawGC === undefined || rawGC === null || rawGC === '') return null;

const machineId   = entry.machine_id   !== undefined ? entry.machine_id : null;
const machineName = String(entry.machine_name || 'UNKNOWN').trim();
const storeKey    = machineId !== null ? ('m' + machineId) : machineName.toUpperCase();

const now       = new Date();
const shiftInfo = getShiftInfo(now);
const shiftKey  = shiftInfo.shift + '_' + shiftInfo.dateLabel;

// ─── per-machine persistent state ────────────────────────────────────────────
const allState = global.get('EAP_SHOT_STATE') || {};
let   st       = allState[storeKey] || { prevGC: null, shotCount: 0, counter: 0, shiftKey: '' };

if (st.shiftKey !== shiftKey) {
  st.shotCount = 0;
  st.counter   = 0;
  st.shiftKey  = shiftKey;
}

const newGC  = String(rawGC).trim();
const prevGC = st.prevGC;
let   shotFired = 0;

if (prevGC !== null && prevGC !== newGC) {
  shotFired    = 1;
  st.shotCount += 1;
  const numGC = parseFloat(newGC);
  if (Number.isFinite(numGC) && numGC > 0) st.counter += 1;
}

st.prevGC          = newGC;
allState[storeKey] = st;
global.set('EAP_SHOT_STATE', allState);

// ─── build row ────────────────────────────────────────────────────────────────
const ts = now.getFullYear() + '-' +
           pad(now.getMonth() + 1) + '-' +
           pad(now.getDate())      + 'T' +
           pad(now.getHours())     + ':' +
           pad(now.getMinutes())   + ':' +
           pad(now.getSeconds());

const row = {
  timestamp          : ts,
  shift              : shiftInfo.shift,
  date_label         : shiftInfo.dateLabel,
  machine_id         : machineId !== null ? machineId : '',
  machine_name       : machineName,
  total_good_count   : newGC,
  machine_shot_count : st.shotCount,
  counter            : st.counter
};

// ─── write ────────────────────────────────────────────────────────────────────
try {
  appendRow(csvFilePath(shiftInfo.shift, shiftInfo.dateLabel), row);
} catch (e) {
  node.warn('CSV write error: ' + e.message);
}

// ─── output ───────────────────────────────────────────────────────────────────
msg.payload = {
  machine_id         : machineId,
  machine_name       : machineName,
  Total_Good_Count   : newGC,
  machine_shot_count : st.shotCount,
  counter            : st.counter,
  shift              : shiftInfo.shift,
  shift_date         : shiftInfo.dateLabel,
  shot_fired         : shotFired
};

node.status({
  fill : shotFired ? 'green' : 'blue',
  shape: 'dot',
  text : machineName + ' GC=' + newGC + ' shots=' + st.shotCount + ' ctr=' + st.counter
});

return msg;

global.set('EAP_SHOT_STATE', {});
node.status({ fill:'yellow', shape:'ring', text:'all shot counters reset ' + new Date().toLocaleTimeString() });
node.warn('EAP_SHOT_STATE cleared manually');
return null;
